"use strict";const strip=require("./strip"),{erase:erase,cursor:cursor}=require("sisteransi"),width=r=>[...strip(r)].length;module.exports=function(r,e){if(!e)return erase.line+cursor.to(0);let t=0;const s=r.split(/\r?\n/);for(let r of s)t+=1+Math.floor(Math.max(width(r)-1,0)/e);return erase.lines(t)};